  "2628": "<span class=\"kr cardname\">定理：⟦0⟧</span>",
  "2629": "点击 ⟦0⟧，按照 ⟦1⟧ 的定义改写门（定义展开）。",
  "2630": "两边是同一个项，点击 = 打开门（=I）。",
  "2631": "插入等式钥匙，改写门中的项（=E）。",
  "2632": "点击 ∀，带着<b>任意</b>元素进入新房间（∀I）。",
  "2633": "点击 ∃，选择一个元素作为见证（∃I）。选择不当可能走入死路。",
  "2634": "这是一扇 ⊥（矛盾）门。用一对矛盾钥匙（如 A 与 ¬A）推出 ⊥，或插入一把 ¬A 钥匙。",
  "2635": "点击 ¬，带着 ⟦0⟧ 进入新房间，以 ⊥ 为目标（→I；¬A 是 A→⊥ 的缩写）。",
  "2636": "点击 →，带着假设进入新房间（→I）。",
  "2637": "点击 ∧，将门分成两扇（∧I）。",
  "2638": "点击 ∨，选择要证明的析取支（∨I）。选错可能走入死路。",
  "2639": "原子命题之门：在这里插入匹配的钥匙。",
  "2640": "<div class=\"lit-box ok\">⟦0⟧灯笼：这扇门有出口（可以证明）。</div>",
  "2641": "<div class=\"lit-box dead\">⟦0⟧灯笼：这扇门是死路，不论怎样使用钥匙都打不开。</div>",
  "2642": "<button type=\"button\" class=\"btn small indb\" data-ind title=\"拆成 0 的基础情形与从 n 到后继的归纳步骤\">⟦0⟧数学归纳法</button>",
  "2643": "<button type=\"button\" class=\"btn small indb ind-off\" data-indoff aria-disabled=\"true\" title=\"本大厅的公理不包含数学归纳法\">⟦0⟧数学归纳法</button>",
  "2644": "<button type=\"button\" class=\"btn small lem\" data-lemma title=\"先证明一个引理，再将它作为钥匙使用\">⟦0⟧提出引理</button>",
  "2645": "<button type=\"button\" class=\"btn small raa\" data-raa title=\"魔法：假设这扇门的否定并推出矛盾（归谬法）\">⟦0⟧反证法（RAA）</button>",
  "2646": "<button type=\"button\" class=\"btn small exf\" data-exfalso title=\"推出矛盾即可打开任意门（⊥E）\">以 ⊥ 为目标（⊥E）</button>",
  "2647": "<div class=\"orpick lem-pick\" role=\"group\" aria-label=\"选择引理\"><div class=\"orpick-q\">你想提出什么引理？</div>",
  "2648": "<div class=\"lem-input\"><input type=\"text\" id=\"lemmaInput\" placeholder=\"输入公式，例如 !x.(P(x) -> R(x))\" aria-label=\"引理公式\" autocomplete=\"off\" spellcheck=\"false\"><button type=\"button\" class=\"btn small primary\" data-lemgo>提出</button><button type=\"button\" class=\"btn small\" data-lemx>取消</button></div>",
  "2649": "<div class=\"note\">输入符号： ∀x 表示 <code>!x.</code>, ∃x 表示 <code>?x.</code>, ∧ 表示 <code>&amp;</code>, ∨ 表示 <code>|</code>, → 表示 <code>-&gt;</code>, ¬ 表示 <code>~</code>, ⊥ 表示 <code>#</code>. 谓词写作 <code>P(x)</code>, equality 表示 <code>a = b</code>, 运算写作 <code>a * b</code>.</div></div>",
  "2650": "<div class=\"orpick\" role=\"group\" aria-label=\"选择要改写的位置\"><div class=\"orpick-q\">在以下位置中选择 ⟦1⟧ in ⟦0⟧, 选择要改写为 ⟦2⟧",
