  "2807": "\n    <h2>成功逃脱！</h2>\n    ⟦0⟧⟦1⟧\n    <p>你已打开以下关卡的全部门： ⟦2⟧ \"⟦3⟧\".⟦4⟧</p>\n    <div class=\"score\"><span><b>⟦5⟧</b> 步</span><span class=\"par\">参考 ⟦6⟧ 步</span>⟦7⟧⟦8⟧</div>⟦9⟧\n    ⟦10⟧\n    ⟦11⟧\n    <h3>完成的证明树</h3>\n    ⟦12⟧\n    <div class=\"ptw\"><div class=\"ptr\" id=\"rpTree\">⟦13⟧</div></div>\n    ⟦14⟧\n    <p class=\"note\">上标数字是假设标签⟦15⟧. 带有 [ ]¹ 的假设由相同编号的 →I、∨E、∃E 或 RAA 解除（即离开房间或分支时不再使用）。</p>\n    ⟦16⟧\n    <p class=\"check⟦17⟧\">⟦18⟧</p>\n    <h3>操作与推理规则</h3>\n    <ol class=\"log\">⟦19⟧</ol>\n    <div class=\"actions\">\n      <button class=\"btn\" type=\"button\" data-cmd=\"retry\">重试</button>\n      <button class=\"btn\" type=\"button\" data-cmd=\"map\">关卡列表</button>\n      ⟦20⟧\n    </div>",
  "2808": "<button type=\"button\" class=\"btn small guide-again\" data-guide=\"clear\">此页面的使用引导</button>",
  "2809": "<span class=\"par\">超出参考步数 ⟦0⟧ 步</span>",
  "2810": "先完成通关！你可以再挑战参考步数。",
  "2811": "<span class=\"par\">反证法 ×⟦0⟧</span>",
  "2812": "（不过，初始假设中包含排中律钥匙）",
  "2813": "（不过，初始假设中包含双重否定消去钥匙）",
  "2814": "<p class=\"note\">使用的定理卡片：⟦0⟧</p>",
  "2815": "<div class=\"rp-ctrl\" role=\"group\" aria-label=\"回放证明\">\n      <button type=\"button\" class=\"btn small\" data-rp=\"first\" aria-label=\"跳至开始\">⏮</button><button type=\"button\" class=\"btn small\" data-rp=\"prev\" aria-label=\"后退一步\">◀</button>\n      <button type=\"button\" class=\"btn small primary\" data-rp=\"play\" id=\"rpPlay\">▶ 播放</button>\n      <button type=\"button\" class=\"btn small\" data-rp=\"next\" aria-label=\"前进一步\">▶</button><button type=\"button\" class=\"btn small\" data-rp=\"last\" aria-label=\"跳至结束\">⏭</button>\n      <span class=\"rp-count\" id=\"rpCount\"></span>\n      <button type=\"button\" class=\"toggle\" data-rp=\"auto\" id=\"rpAuto\" aria-pressed=\"⟦0⟧\"><span class=\"sw-track\"><span class=\"sw-knob\"></span></span>通关后自动回放</button></div>",
  "2816": "（对应证明项中 <span class=\"nm\">x</span> 的下标）",
  "2817": "<h3>证明项</h3><div class=\"term\">⟦0⟧</div>",
  "2818": "类型检查通过：⟦0⟧⊢ 此项 : ⟦1⟧",
