  "3123": "<h2>教程</h2>⟦0⟧<h3>⟦1⟧⟦2⟧：⟦3⟧</h3><div class=\"tut-box\" id=\"tutBox\" aria-label=\"操作演示\"></div><p class=\"tut-text\">⟦4⟧</p>⟦5⟧<details class=\"tut-all\"><summary>全部教程</summary>⟦6⟧</details><div class=\"actions\"><button class=\"btn primary\" type=\"button\" data-cmd=\"close\">关闭</button></div>",
  "3124": "<div class=\"tut-here\"><span class=\"note\">本房间新学： </span>⟦0⟧</div>",
  "3125": "<div class=\"tut-here\"><span class=\"note\">本房间没有新增操作。最近学到的是： </span>⟦0⟧</div>",
  "3126": "<div class=\"tut-ctrl\"><button type=\"button\" class=\"btn small\" data-tutstep=\"prev\" ⟦0⟧>上一步</button><span class=\"tut-dots\">⟦1⟧</span><button type=\"button\" class=\"btn small\" data-tutstep=\"next\" ⟦2⟧>下一步</button></div>",
  "3127": "顶部工具栏",
  "3128": "顶部可打开教程（展示操作过程）、关卡列表、撤销（也可按 Z）、重新开始和玩法说明。出现新操作时，“教程”按钮会显示“新”。",
  "3129": "关卡信息",
  "3130": "显示本层名称、参考步数和个人纪录。游戏的一步操作未必对应一次推理规则的使用；定义展开也算一步。已通关关卡和定理卡片会保存。",
  "3131": "关卡名称",
  "3132": "显示关卡编号和名称。每层最后一关是首领关卡。",
  "3133": "待证明的相继式",
  "3134": "⊢ 左侧是初始假设（钥匙），右侧是证明目标（门）。标为 ⊬ 的题目则要求用反例说明不可证明。",
  "3135": "本房间介绍",
  "3136": "说明新的规则和概念，可用 ▾ 展开或收起。",
  "3137": "门面板标题",
  "3138": "显示门的数量、下一扇门、最近的推理规则，以及实际步数与参考步数。",
  "3139": "钥匙",
  "3140": "当前可用的假设及已推出的命题。入口大厅存放初始钥匙，房间内存放在其中得到的钥匙。可将钥匙拖到门或另一把钥匙上，或先点击选择再点击使用。",
  "3141": "待打开的门",
  "3142": "当前证明目标。点击彩色联结词（∧、→ 等），即可应用其推理规则。反证法等特殊操作位于门下方。",
  "3143": "证明树",
  "3144": "每一步操作都会构造自然演绎证明树。⋮ 表示尚未完成的目标。鼠标悬停在符号上可预览变化。",
  "3145": "提示与记录",
  "3146": "提示逐步揭示。操作记录列出迄今所有步骤及相应推理规则。",
  "3150": "<span class=\"hfig-tag\">房间钥匙</span>",
  "3151": "<span class=\"hfig-tag door-tag\">门</span>",
  "3158": "钥匙、门与房间",
  "3162": "操作与推理规则",
  "3165": "进阶内容",
  "3167": "Lean 模式",
  "3171": "如果你想亲自编写 Lean 战术来完成证明，",
  "3172": " 是不错的选择。",
  "3173": "<h2>玩法说明</h2><div class=\"help-tabs\" role=\"tablist\">⟦0⟧</div><div class=\"help-page\">⟦1⟧</div><div class=\"actions\">⟦2⟧⟦3⟧<button class=\"btn primary\" type=\"button\" data-cmd=\"close\">关闭</button></div>",
  "3174": "<b>操作示例：</b>⟦0⟧",
  "3175": "模型已经重置，点击“撤销”可以恢复。",
  "3176": "已恢复初始状态，点击“撤销”可以恢复。",
  "3177": "迷宫模式：开启（显示门与石墙装饰）",
  "3178": "迷宫模式：关闭（标准外观）",
  "3179": "亮度：⟦0⟧⟦1⟧",
  "3180": "（跟随系统设置）",
  "3181": "剧情模式：开启",
  "3182": "剧情模式：关闭",
  "3183": "灯笼发现 ⟦0⟧ 扇死路。使用“撤销”取消导致死路的操作。",
  "3184": "灯笼显示当前 ⟦0⟧ 扇未打开的门都存在出口。",
  "3185": "全图视图：显示整棵证明树的房间与门。只能在当前门进行操作，点击其他门可以移动过去。",
  "3186": "房间视图：仅显示通往当前位置的房间。",
  "3187": "在 ∀I 和 ∃E 中自行选择元素名字。违反固有变元条件的名字会被拒绝并提示原因。",
  "3188": "在 ∀I 和 ∃E 中自动选择尚未出现过的名字。",
  "3189": "Lean 模式：开启（自然演绎证明树上方显示相应的 Lean 4 代码）",
  "3190": "Lean 模式：关闭",
  "3191": "无限制模式：开启（所有层均可游玩）",
  "3192": "无限制模式：关闭（通关上一层后解锁下一层）",
  "3193": "<h2>重置游戏进度？</h2>\n        <p>以下记录将全部清除。 <b>此操作无法撤销。</b></p>\n        <ul class=\"help-list\"><li>各关卡通关记录与最佳步数</li><li>已获得的定理卡片</li><li>已阅读的引导、教程与帮助页面（“新”标记和首次引导将重新出现）</li></ul>\n        <label class=\"reset-prefs\"><input type=\"checkbox\" id=\"resetPrefs\" checked> 同时将开关恢复默认设置</label>\n        <p class=\"note\">默认设置仅开启“剧情” (“显示证明项（λ 项）”“Lean 模式”“无限制模式”“自行选择名字”和“通关后自动回放”均关闭, 亮度为“自动”). 当前语言设置会保留。 如果同时重置设置，页面会重新加载。</p>\n        <div class=\"actions\"><button class=\"btn\" type=\"button\" data-cmd=\"close\">取消</button><button class=\"btn danger\" type=\"button\" data-cmd=\"resetDo\">重置</button></div>",
  "3194": "已重置全部进度。",
  "3195": "⟦0⟧：⟦1⟧",
  "3196": "本大厅的公理不含数学归纳法。没有归纳法，也许无法打开这扇门。",
  "3197": "已退回进入死路之前。",
  "3198": "点击选择（或输入）一个引理公式。门将分为“证明引理”与“使用引理”两扇。",
  "3199": "点击选择一个元素作见证。将增加一条对该元素证明存在命题的 ∃I 推理线。",
  "3200": "点击选择一个元素用于实例化。手头证明部件中将出现一段 ∀E 证明。",
  "3201": "点击选择要证明左侧还是右侧。将增加一条只针对该侧的 ∨I 推理线。"
